ft","disciplines":["whitewater"]},{"category":"paddle","brand":"Werner","model":"Surge","variant":"1 piece, straight shaft","disciplines":["whitewater"]},{"category":"paddle","brand":"Werner","model":"Surge","variant":"4 piece, straight shaft","disciplines":["whitewater"]},{"category":"paddle","brand":"Werner","model":"Twist","variant":"1 piece, bent shaft","disciplines":["freestyle"]},{"category":"paddle","brand":"Werner","model":"Twist","variant":"1 piece, straight shaft","disciplines":["freestyle"]},{"category":"paddle","brand":"Werner","model":"Twist","variant":"4 piece, straight shaft","disciplines":["freestyle"]}]$seed$::jsonb) AS s(
        category material_category, brand text, model text, variant text,
        disciplines material_discipline[]
